using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for maximum throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (values.Length == 1)
            return (values[0], values[0]);

        if (Vector512.IsHardwareAccelerated && values.Length >= Vector512<float>.Count * 2)
            return FindMinMaxVector512(values);

        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 2)
            return FindMinMaxVector256(values);

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 2)
            return FindMinMaxVector128(values);

        return FindMinMaxScalar(values);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMaxVector512(ReadOnlySpan<float> values)
    {
        ref float ptr = ref MemoryMarshal.GetReference(values);
        int count = Vector512<float>.Count;
        int len = values.Length;
        int lastBlockStart = len - (len % count);

        var vMin0 = Vector512.LoadUnsafe(ref ptr);
        var vMax0 = vMin0;
        var vMin1 = vMin0;
        var vMax1 = vMax0;

        int i = count;
        int unrolledEnd = lastBlockStart - count;
        // Process two vectors per iteration to exploit ILP
        for (; i <= unrolledEnd; i += count * 2)
        {
            var v0 = Vector512.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector512.LoadUnsafe(ref ptr, (nuint)(i + count));
            vMin0 = Vector512.Min(vMin0, v0);
            vMax0 = Vector512.Max(vMax0, v0);
            vMin1 = Vector512.Min(vMin1, v1);
            vMax1 = Vector512.Max(vMax1, v1);
        }

        // Handle remaining full vector
        for (; i < lastBlockStart; i += count)
        {
            var v = Vector512.LoadUnsafe(ref ptr, (nuint)i);
            vMin0 = Vector512.Min(vMin0, v);
            vMax0 = Vector512.Max(vMax0, v);
        }

        vMin0 = Vector512.Min(vMin0, vMin1);
        vMax0 = Vector512.Max(vMax0, vMax1);

        // Reduce 512 -> scalar
        var lo256 = vMin0.GetLower();
        var hi256 = vMin0.GetUpper();
        var minV = Vector256.Min(lo256, hi256);
        var loMax256 = vMax0.GetLower();
        var hiMax256 = vMax0.GetUpper();
        var maxV = Vector256.Max(loMax256, hiMax256);

        var min128 = Vector128.Min(minV.GetLower(), minV.GetUpper());
        var max128 = Vector128.Max(maxV.GetLower(), maxV.GetUpper());

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Process tail elements
        for (; i < len; i++)
        {
            float val = Unsafe.Add(ref ptr, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMaxVector256(ReadOnlySpan<float> values)
    {
        ref float ptr = ref MemoryMarshal.GetReference(values);
        int count = Vector256<float>.Count;
        int len = values.Length;
        int lastBlockStart = len - (len % count);

        var vMin0 = Vector256.LoadUnsafe(ref ptr);
        var vMax0 = vMin0;
        var vMin1 = vMin0;
        var vMax1 = vMax0;

        int i = count;
        int unrolledEnd = lastBlockStart - count;
        for (; i <= unrolledEnd; i += count * 2)
        {
            var v0 = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector256.LoadUnsafe(ref ptr, (nuint)(i + count));
            vMin0 = Vector256.Min(vMin0, v0);
            vMax0 = Vector256.Max(vMax0, v0);
            vMin1 = Vector256.Min(vMin1, v1);
            vMax1 = Vector256.Max(vMax1, v1);
        }

        for (; i < lastBlockStart; i += count)
        {
            var v = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            vMin0 = Vector256.Min(vMin0, v);
            vMax0 = Vector512.Max(vMax0, v);
        }

        vMin0 = Vector256.Min(vMin0, vMin1);
        vMax0 = Vector256.Max(vMax0, vMax1);

        var min128 = Vector128.Min(vMin0.GetLower(), vMin0.GetUpper());
        var max128 = Vector128.Max(vMax0.GetLower(), vMax0.GetUpper());

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        for (; i < len; i++)
        {
            float val = Unsafe.Add(ref ptr, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMaxVector128(ReadOnlySpan<float> values)
    {
        ref float ptr = ref MemoryMarshal.GetReference(values);
        int count = Vector128<float>.Count;
        int len = values.Length;
        int lastBlockStart = len - (len % count);

        var vMin0 = Vector128.LoadUnsafe(ref ptr);
        var vMax0 = vMin0;
        var vMin1 = vMin0;
        var vMax1 = vMax0;

        int i = count;
        int unrolledEnd = lastBlockStart - count;
        for (; i <= unrolledEnd; i += count * 2)
        {
            var v0 = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector128.LoadUnsafe(ref ptr, (nuint)(i + count));
            vMin0 = Vector128.Min(vMin0, v0);
            vMax0 = Vector128.Max(vMax0, v0);
            vMin1 = Vector128.Min(vMin1, v1);
            vMax1 = Vector128.Max(vMax1, v1);
        }

        for (; i < lastBlockStart; i += count)
        {
            var v = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            vMin0 = Vector128.Min(vMin0, v);
            vMax0 = Vector128.Max(vMax0, v);
        }

        vMin0 = Vector128.Min(vMin0, vMin1);
        vMax0 = Vector128.Max(vMax0, vMax1);

        float min = HorizontalMin(vMin0);
        float max = HorizontalMax(vMax0);

        for (; i < len; i++)
        {
            float val = Unsafe.Add(ref ptr, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin(Vector128<float> v)
    {
        // Shuffle and reduce: 4 floats -> 1 min
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Min(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Min(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax(Vector128<float> v)
    {
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Max(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Max(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            float val = values[i];
            if (val < min) min = val;
            if (val > max) max = val;
        }
        return (min, max);
    }
}

